package com.github.kusa233.neko

import com.github.kusa233.neko.diagnostics.Severity
import com.github.kusa233.neko.source.SourceFile
import java.nio.file.Files
import java.nio.file.Path
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue

/**
 * Compiles `Sample.neko` itself, exactly as checked in.
 *
 * The other tests check rules in isolation; this one is the acceptance test. It reads the real
 * sample from disk, compiles it, and runs the generated bytecode, so the whole pipeline — including
 * the `locate` package, the `private val` field, the returned lambda, and the `throws` clause — is
 * verified against the file the task was specified with.
 */
class SampleEndToEndTest {

    private fun samplePath(): Path =
        TestSupport.projectDirectory.resolve("samples/com/github/kusa233/neko/sample/Sample.neko")

    private fun exceptionSamplePath(): Path =
        TestSupport.projectDirectory.resolve(
            "samples/com/github/kusa233/neko/sample/ExceptionSample.neko",
        )

    private fun nyaSamplePath(): Path =
        TestSupport.projectDirectory.resolve(
            "samples/com/github/kusa233/neko/sample/NyaSample.neko",
        )

    private fun enumSamplePath(): Path =
        TestSupport.projectDirectory.resolve(
            "samples/com/github/kusa233/neko/sample/EnumSample.neko",
        )

    private fun purrSamplePath(): Path =
        TestSupport.projectDirectory.resolve(
            "samples/com/github/kusa233/neko/sample/PurrSample.neko",
        )

    private fun forSamplePath(): Path =
        TestSupport.projectDirectory.resolve(
            "samples/com/github/kusa233/neko/sample/ForSample.neko",
        )

    /**
     * Compiles one sample together with the Neko standard library, as the build does.
     *
     * The library lives in `stdlib` and is ordinary Neko source, so a sample that raises
     * only compiles when both are handed to the compiler at once — a class file's supertypes are
     * resolved when it is loaded, and `EarlyEmitException` is one of them.
     */
    private fun compileSample(path: Path, outputDirectory: Path? = null): CompilationResult {
        val source = SourceFile(
            name = path.fileName.toString(),
            content = Files.readString(path),
            path = path,
        )
        return Compiler.compileProgram(
            TestSupport.standardLibrarySources() + source,
            outputDirectory = outputDirectory,
        )
    }

    /**
     * Whether [internalName] belongs to the standard library rather than to the sample under test.
     *
     * The library is compiled together with every program, so its classes are always among the output;
     * a test that asserts *which* classes a sample produced has to leave them out. Matching on the
     * package rather than on a list of names keeps that true as the library grows.
     */
    private fun isStandardLibraryClass(internalName: String): Boolean =
        internalName.contains("EmitExtractor") ||
            internalName.endsWith("/EarlyEmitException") ||
            internalName.startsWith("com/github/kusa233/neko/stdlib/")

    @Test
    fun `the sample compiles without errors`() {
        val result = compileSample(samplePath())
        assertTrue(
            !result.hasErrors,
            "Sample.neko must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )
    }

    @Test
    fun `the sample produces the classes its package and declarations imply`() {
        val result = compileSample(samplePath())
        // The sample's own class, its lambda's class, and the interface that lambda's function type
        // needs. The library's classes are emitted too, because the library is compiled with it.
        val emitted = result.classes.keys.filterNot { isStandardLibraryClass(it) }
        assertEquals(
            setOf(
                "com/github/kusa233/neko/sample/Sample",
                "com/github/kusa233/neko/sample/Sample\$Lambda\$0",
                "com/github/kusa233/neko/sample/Neko\$Function\$0",
            ),
            emitted.toSet(),
            "unexpected set of generated classes",
        )
    }

    @Test
    fun `the sample writes class files that the JVM can load and run`() {
        val directory = Files.createTempDirectory("neko-sample")
        val result = compileSample(samplePath(), outputDirectory = directory)
        assertTrue(!result.hasErrors, "the sample must compile before it can be run")

        val classFile = directory.resolve("com/github/kusa233/neko/sample/Sample.class")
        assertTrue(Files.exists(classFile), "Sample.class should have been written to $directory")

        // `Sample.main` calls `field1`, `variable()`, `lambda()` and `controlFlow()`. Its output is
        // the sample's own documented behaviour, line by line.
        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.Sample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            main.invoke(null, arrayOf<String>())
        } finally {
            System.setOut(original)
        }

        assertEquals(
            listOf(
                "123",                              // println(field1)
                "Hell world!",                      // variable(): println(str)
                "new value",                        // variable(): str = "new value"; println(str)
                "a more than b and more than c",    // controlFlow(): `a > b > c` holds
                "Correct a",                        // controlFlow(): `when (a)` matches 3
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the compiled sample should print exactly what its comments promise",
        )
    }

    @Test
    fun `the exception sample compiles without errors`() {
        val result = compileSample(exceptionSamplePath())
        assertTrue(
            !result.hasErrors,
            "ExceptionSample.neko must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )
    }

    @Test
    fun `the exception sample produces the classes its emit lowering implies`() {
        val result = compileSample(exceptionSamplePath())
        // The sample's own class and the extractor literal's class. The `EmitExtractorN` interfaces
        // and `EarlyEmitException` come from `samples/library`, which is compiled in the same run, so
        // they are emitted alongside rather than supplied from outside.
        val emitted = result.classes.keys.filterNot { isStandardLibraryClass(it) }
        assertEquals(
            setOf(
                "com/github/kusa233/neko/sample/ExceptionSample",
                "com/github/kusa233/neko/sample/ExceptionSample\$Emit\$0",
            ),
            emitted.toSet(),
            "unexpected set of generated classes",
        )
        assertTrue(
            result.classes.containsKey("com/github/kusa233/neko/stdlib/emit/EarlyEmitException"),
            "the standard library must be emitted by the same run: ${result.classes.keys}",
        )
    }

    @Test
    fun `the exception sample lowers raise to the exception the spec describes`() {
        val result = compileSample(exceptionSamplePath())
        val bytes = result.classes.getValue("com/github/kusa233/neko/sample/ExceptionSample")

        val methods = mutableMapOf<String, MutableList<String>>()
        org.objectweb.asm.ClassReader(bytes).accept(
            object : org.objectweb.asm.ClassVisitor(org.objectweb.asm.Opcodes.ASM9) {
                override fun visitMethod(
                    access: Int,
                    name: String,
                    descriptor: String,
                    signature: String?,
                    thrown: Array<out String>?,
                ): org.objectweb.asm.MethodVisitor? {
                    methods.getOrPut(name) { mutableListOf() }.add(descriptor)
                    if (name == "emitTest") {
                        methods.getOrPut("emitTest:thrown") { mutableListOf() }
                            .addAll(thrown.orEmpty().toList())
                    }
                    return null
                }
            },
            org.objectweb.asm.ClassReader.SKIP_CODE,
        )

        // The spec's own names: `test$emit$0()` is the builder, and it is `private static` and
        // returns `Object[]`.
        assertEquals<List<String>>(
            listOf("(II)[Ljava/lang/Object;"),
            methods["emitTest\$emit\$0"].orEmpty(),
            "the raise builder should box both values into an Object[]",
        )
        // `raise` is a throw, so the raising function declares it and the caller can catch it.
        assertEquals<List<String>>(
            listOf("com/github/kusa233/neko/stdlib/emit/EarlyEmitException"),
            methods["emitTest:thrown"].orEmpty(),
            "a raising function must record EarlyEmitException",
        )
    }

    @Test
    fun `the exception sample runs and prints both raised values`() {
        val directory = Files.createTempDirectory("neko-exception-sample")
        val result = compileSample(exceptionSamplePath(), outputDirectory = directory)
        assertTrue(!result.hasErrors, "the exception sample must compile before it can be run")

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.ExceptionSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            main.invoke(null, arrayOf<String>())
        } finally {
            System.setOut(original)
        }

        // `try emitTest(true) { emit1, emit2 -> ... }` and `raise 123, 456`: the extractor prints both
        // values, so the output starts "123" then "456". This is the sample's whole point — the values
        // crossed a frame boundary by being thrown, not returned. The line that follows the `raise`
        // is the unreachable one, and `yield 1` is what the `try` expression is worth, so the
        // `println(result)` that follows it prints that yielded `1`.
        assertEquals(
            listOf("123", "456", "1"),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the raised values should reach the extractor in order, then the yield should print",
        )
    }

    @Test
    fun `the nya sample runs every check and shows what a false one means`() {
        val directory = Files.createTempDirectory("neko-nya-sample")
        val result = compileSample(nyaSamplePath(), outputDirectory = directory)
        assertTrue(!result.hasErrors, "the nya sample must compile before it can be run")

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.NyaSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            main.invoke(null, arrayOf<String>())
        } finally {
            System.setOut(original)
        }

        // Every check that must hold does, so the run reaches the end. The `4` is the narrow read
        // `nya box != null` is what allows; the two lines after it are the failure block of the check
        // that does not hold — which no longer ends the call — and the two numbers at the end are the
        // value form answering by which block ran. `caught`/`continued` are the block answering a
        // check that failed inside the call it was watching, rather than one that came back false.
        assertEquals(
            listOf(
                "3",
                "6",
                "ready",
                "flag",
                "4",
                "handled: 1 == 2 was false",
                "recovered",
                "caught: the check inside guarded failed",
                "continued",
                "0",
                "1",
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the sample should run every check and show what a false condition means",
        )
    }

    @Test
    fun `the enum sample prints each constant the way java dot lang Enum does`() {
        // The sample's expected output is its own comments, one per `println`. If `miao class` emitted
        // static fields instead of a real enum, `name()` and the `println` of a constant would both
        // have nothing to answer with — which is exactly what this compares.
        val directory = Files.createTempDirectory("neko-enum-sample")
        val result = compileSample(enumSamplePath(), outputDirectory = directory)
        assertTrue(
            !result.hasErrors,
            "the enum sample must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.EnumSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            main.invoke(null, arrayOf<String>())
        } finally {
            System.setOut(original)
        }

        assertEquals(
            listOf(
                "GREEN",
                "1",
                "GREEN",
                "true",
                "false",
                "200",
                "gone",
                "1",
                "fine",
                "gone",
                "true",
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the sample should print the names, positions and payloads its comments claim",
        )
    }

    @Test
    fun `the purr sample's blocks guard and release the way its comments claim`() {
        // The sample's expected output is its own comments, one per `println`. What makes this worth
        // running rather than just compiling is that a lock leak does not show up as a wrong answer
        // until something tries to take the same lock again — which the sample does, several times
        // over, so a missing unlock deadlocks here instead of passing quietly.
        val directory = Files.createTempDirectory("neko-purr-sample")
        val result = compileSample(purrSamplePath(), outputDirectory = directory)
        assertTrue(
            !result.hasErrors,
            "the purr sample must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.PurrSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            // Joined with a timeout: the failure mode of a forgotten unlock is a deadlock, and a test
            // that hangs says less than one that fails.
            val thread = Thread { main.invoke(null, arrayOf<String>()) }
            thread.isDaemon = true
            thread.start()
            thread.join(30_000)
            assertTrue(!thread.isAlive, "the purr sample deadlocked: a lock was never released")
        } finally {
            System.setOut(original)
        }

        assertEquals(
            listOf(
                "5",
                "42",
                "2",
                "2",
                "1",
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the sample should print the totals its comments claim",
        )
    }

    @Test
    fun `the for sample runs and prints the values its comments claim`() {
        // The comments in `ForSample.neko` each name the value the `println` above them should print,
        // so this checks the language against its own documentation. Running it is what makes that a
        // real check: a loop that iterates once too often, or an `iinc` on the wrong type, still
        // compiles and only shows up as a wrong number here.
        val directory = Files.createTempDirectory("neko-for-sample")
        val result = compileSample(forSamplePath(), outputDirectory = directory)
        assertTrue(
            !result.hasErrors,
            "the for sample must compile:\n${result.renderDiagnostics().joinToString("\n")}",
        )

        val loader = java.net.URLClassLoader(arrayOf(directory.toUri().toURL()), javaClass.classLoader)
        val type = Class.forName("com.github.kusa233.neko.sample.ForSample", true, loader)
        val main = type.getMethod("main", Array<String>::class.java)

        val original = System.out
        val buffer = java.io.ByteArrayOutputStream()
        System.setOut(java.io.PrintStream(buffer, true, Charsets.UTF_8))
        try {
            // The array loop prints this program's own `main` arguments, so passing none is what makes
            // that section print nothing — which is itself the assertion that an empty array iterates
            // zero times rather than once with a null element.
            main.invoke(null, arrayOf<String>())
        } finally {
            System.setOut(original)
        }

        assertEquals(
            listOf(
                "15",   // 1 + 2 + 3 + 4 + 5
                "3", "2", "1", // counting down
                "4",    // 1, 3, 9, 27
                "6",    // 0 + 2 + 4
                "6",    // 2 * 3 rows and columns
                "miao", "nya", "purr", // the Iterable
                "3",    // how many words it yielded
                "11", "9", "2", "101", // ++ and -- on int, byte and long
                "64",   // 8 * 8 is the first square over 50
            ),
            buffer.toString(Charsets.UTF_8).replace("\r\n", "\n").trim().lines(),
            "the sample should print the values its comments claim",
        )
    }

    @Test
    fun `the exception sample's try expression is worth the extractor's yield`() {
        val result = compileSample(exceptionSamplePath())
        val bytes = result.classes.getValue("com/github/kusa233/neko/sample/ExceptionSample\$Emit\$0")

        // The extractor's body writes `yield 1`, so it implements the value-returning family and its
        // `invoke` answers an `Object` — the boxed `1` the `try` expression receives when the call
        // `raise`s instead of returning.
        var interfaceName: String? = null
        val methods = mutableMapOf<String, String>()
        org.objectweb.asm.ClassReader(bytes).accept(
            object : org.objectweb.asm.ClassVisitor(org.objectweb.asm.Opcodes.ASM9) {
                override fun visit(
                    version: Int,
                    access: Int,
                    name: String,
                    signature: String?,
                    superName: String?,
                    interfaces: Array<out String>?,
                ) {
                    interfaceName = interfaces?.firstOrNull()
                }

                override fun visitMethod(
                    access: Int,
                    name: String,
                    descriptor: String,
                    signature: String?,
                    thrown: Array<out String>?,
                ): org.objectweb.asm.MethodVisitor? {
                    methods[name] = descriptor
                    return null
                }
            },
            org.objectweb.asm.ClassReader.SKIP_CODE,
        )

        assertEquals(
            "com/github/kusa233/neko/stdlib/emit/EmitExtractorWithResult2",
            interfaceName,
            "an extractor that yields must implement the value-returning family",
        )
        assertEquals(
            "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
            methods["invoke"],
            "the yielding invoke returns the value, erased to Object",
        )
    }

    /**
     * Analyses [content] as a program that includes the standard library, and returns the errors.
     *
     * Parsing and analysis are driven directly rather than through [Compiler] because these tests
     * assert on diagnostics that code generation never reaches — an unreachable statement, a
     * redeclared variable. The library is still part of the program, because a `raise` without it is
     * rejected before the rule under test is ever considered.
     */
    private fun analyzeWithLibrary(name: String, content: String): List<com.github.kusa233.neko.diagnostics.Diagnostic> {
        val diagnostics = com.github.kusa233.neko.diagnostics.DiagnosticBag()
        val files = TestSupport.standardLibrarySources().map {
            com.github.kusa233.neko.parser.Parser(it, diagnostics).parseFile()
        } + com.github.kusa233.neko.parser.Parser(SourceFile(name, content), diagnostics).parseFile()
        check(!diagnostics.hasErrors) {
            "the library and the sample must parse, but got:\n" +
                diagnostics.diagnostics.joinToString("\n") { it.toString() }
        }

        val program = com.github.kusa233.neko.ast.NekoProgram(files)
        com.github.kusa233.neko.analyzer.Analyzer(program, diagnostics).analyze()
        return diagnostics.diagnostics.filter { it.severity == Severity.ERROR }
    }

    /**
     * The sample's unreachable statement after `raise` must be reported at error level, on the line
     * the comment names.
     */
    @Test
    fun `the statement after raise is an error at the line the sample marks`() {
        val original = Files.readString(exceptionSamplePath())
        val uncommented = original.replace(
            "// Unreachable, notice as error level.",
            "println(\"unreachable\")",
        )
        assertTrue(uncommented != original, "the sample should still mark the unreachable line")

        val error = analyzeWithLibrary("ExceptionSample.neko", uncommented).single()
        assertEquals(
            "unreachable statement: execution cannot continue past the preceding 'raise'",
            error.message,
        )
        assertEquals(
            TestSupport.locationOf(uncommented, "println(\"unreachable\")"),
            "${error.span?.line}:${error.span?.column}",
            "the error belongs where the sample's comment sits",
        )
    }

    @Test
    fun `the sample's emit clause reaches the class file`() {
        val result = compileSample(exceptionSamplePath())
        val bytes = result.classes.getValue("com/github/kusa233/neko/sample/ExceptionSample")
        // Read the class back with ASM rather than by running it: the point here is the metadata.
        //
        // The sample never writes a `throws` clause — that keyword is gone from the language. It
        // writes `} emit [int, int]`, which is the same promise in the language's own spelling: the
        // function can leave by raising rather than by returning. The lowering must still record
        // `EarlyEmitException` in the class file, so a JVM tool reading it sees the failure mode.
        val reader = org.objectweb.asm.ClassReader(bytes)
        val exceptions = mutableListOf<String>()
        reader.accept(
            object : org.objectweb.asm.ClassVisitor(org.objectweb.asm.Opcodes.ASM9) {
                override fun visitMethod(
                    access: Int,
                    name: String,
                    descriptor: String,
                    signature: String?,
                    thrown: Array<out String>?,
                ): org.objectweb.asm.MethodVisitor? {
                    if (name == "emitTest") exceptions += thrown.orEmpty()
                    return null
                }
            },
            org.objectweb.asm.ClassReader.SKIP_CODE,
        )
        assertEquals(
            listOf("com/github/kusa233/neko/stdlib/emit/EarlyEmitException"),
            exceptions,
            "an 'emit' clause belongs in the class file's Exceptions attribute",
        )
    }

    @Test
    fun `the output directory the compiler is given is inside the project`() {
        // The build hands the compiler `neko-compile/classes`, resolved against the project
        // directory. Asserting the shape here catches a change to that convention — a path that
        // escapes the project (a drive-relative one, say) writes the class files somewhere the
        // `runNekoSample` task would not find them.
        val relative = Path.of(TestSupport.OUTPUT_DIRECTORY)
        assertFalse(relative.isAbsolute, "the output path must be relative, not absolute")
        assertEquals("neko-compile", relative.first().toString())
        assertEquals("classes", relative.last().toString())

        val resolved = TestSupport.projectDirectory.resolve(relative).normalize()
        assertTrue(
            resolved.startsWith(TestSupport.projectDirectory),
            "the output directory must stay inside the project, but was $resolved",
        )
        assertEquals("classes", resolved.fileName.toString())
    }

    @Test
    fun `the sample's commented-out line is a genuine error`() {
        // Sample lines 14-15 are `// Error to compile:` / `// str: string = "new value"`. Uncommenting
        // that line must fail, at that line, pointing at the redeclared name — this is the rule the
        // sample's comments exist to state.
        val original = Files.readString(samplePath())
        val uncommented = original.replace(
            "// str: string = \"new value\"",
            "str: string = \"new value\"",
        )
        assertTrue(uncommented != original, "the sample should still contain the commented-out line")

        val error = analyzeWithLibrary("Sample.neko", uncommented).single()
        assertEquals(
            "variable 'str' is already declared in this scope",
            error.message,
        )
        // The positions are derived from the sample rather than written out, so moving the comment
        // — as editing the sample does — cannot leave a stale line number behind.
        assertEquals(
            TestSupport.locationOf(uncommented, "str: string = \"new value\""),
            "${error.span?.line}:${error.span?.column}",
            "the error belongs on the sample's commented-out line",
        )
        assertEquals(
            TestSupport.locationOf(uncommented, "str: string = \"Hell"),
            "${error.notes.single().span?.line}:${error.notes.single().span?.column}",
            "the note should point at the sample's first declaration of 'str'",
        )
    }
}
